const NeuralCore: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const scrollYRef = useRef(0);
  const requestRef = useRef<number>(0);

  useEffect(() => {
    if (!containerRef.current) return;

    let width = window.innerWidth;
    let height = window.innerHeight;

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, width / height, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });

    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    containerRef.current.appendChild(renderer.domElement);

    // Optimized Geometry: Octahedron for a sharper "engineered" look
    const geometry = new THREE.OctahedronGeometry(1.6, 6);
    const shellGeometry = new THREE.OctahedronGeometry(1.8, 3);

    // Core Material: Polished, High-Fidelity
    const material = new THREE.MeshStandardMaterial({
      color: 0x0F211D, 
      roughness: 0.1,
      metalness: 0.8,
      transparent: true,
      opacity: 0.9,
    });

    // Shell Material: Technical Wireframe
    const shellMat = new THREE.MeshBasicMaterial({
        color: 0xD4FF3F,
        wireframe: true,
        transparent: true,
        opacity: 0.08
    });

    const mesh = new THREE.Mesh(geometry, material);
    const shell = new THREE.Mesh(shellGeometry, shellMat);

    const group = new THREE.Group();
    group.add(mesh);
    group.add(shell);
    scene.add(group);

    // Dynamic Lighting
    const mainLight = new THREE.SpotLight(0xD4FF3F, 100);
    mainLight.position.set(10, 10, 10);
    scene.add(mainLight);

    const backLight = new THREE.PointLight(0xFFFFFF, 20);
    backLight.position.set(-10, -10, -5);
    scene.add(backLight);

    const ambientLight = new THREE.AmbientLight(0xFFFFFF, 0.5);
    scene.add(ambientLight);

    camera.position.z = 5;

    const initialPositions = new Float32Array(geometry.attributes.position.array);

    let mouseX = 0, mouseY = 0, targetX = 0, targetY = 0;

    const handleMouseMove = (e: MouseEvent) => {
      mouseX = (e.clientX / window.innerWidth) - 0.5;
      mouseY = (e.clientY / window.innerHeight) - 0.5;
    };

    const handleScroll = () => {
      scrollYRef.current = window.scrollY;
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('scroll', handleScroll, { passive: true });

    const animate = (time: number) => {
      requestRef.current = requestAnimationFrame(animate);

      // Noise deformation on the core
      const positions = geometry.attributes.position.array;
      for (let i = 0; i < positions.length; i += 3) {
        const x = initialPositions[i];
        const y = initialPositions[i + 1];
        const z = initialPositions[i + 2];
        const noise = Math.sin(x * 2.0 + time * 0.001) * 0.1 + Math.cos(y * 2.0 + time * 0.001) * 0.1;
        positions[i] = x * (1 + noise);
        positions[i+1] = y * (1 + noise);
        positions[i+2] = z * (1 + noise);
      }
      geometry.attributes.position.needsUpdate = true;

      // Pulse effect synced with time
      const pulse = 1 + Math.sin(time * 0.002) * 0.05;
      mesh.scale.setScalar(pulse);
      shell.scale.setScalar(pulse * 1.05);

      // Counter-rotations for mechanical feel
      mesh.rotation.y += 0.0015;
      mesh.rotation.x += 0.0008;
      shell.rotation.y -= 0.003;
      shell.rotation.z += 0.001;

      targetX += (mouseX - targetX) * 0.05;
      targetY += (mouseY - targetY) * 0.05;

      const scrollFactor = Math.min(scrollYRef.current * 0.001, 3);
      group.position.x = targetX * 1.5;
      group.position.y = (-targetY * 1.5) - (scrollFactor * 0.6);

      const scale = Math.max(0.6, 1 - (scrollFactor * 0.1));
      group.scale.setScalar(scale);

      renderer.render(scene, camera);
    };

    requestRef.current = requestAnimationFrame(animate);

    const handleResize = () => {
      width = window.innerWidth;
      height = window.innerHeight;
      camera.aspect = width / height;
      camera.updateProjectionMatrix();
      renderer.setSize(width, height);
    };

    window.addEventListener('resize', handleResize);

    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('scroll', handleScroll);
      window.removeEventListener('resize', handleResize);

      if (containerRef.current && renderer.domElement) {
        containerRef.current.removeChild(renderer.domElement);
      }

      geometry.dispose();
      shellGeometry.dispose();
      material.dispose();
      shellMat.dispose();
      renderer.dispose();
    };
  }, []);

  return <div ref={containerRef} className="fixed inset-0 z-0 pointer-events-none opacity-90" />;
};

