import React, { useState, useEffect } from 'react';

const Header: React.FC = () => {
  const [scrolled, setScrolled] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    if (isMenuOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'auto';
    }
  }, [isMenuOpen]);

  const navLinks = [
    { name: 'Start', href: '#hero' },
    { name: 'Works', href: '#projects' },
    { name: 'Expertise', href: '#services' },
    { name: 'Story', href: '#about' },
  ];

  const handleNavClick = (e: React.MouseEvent<HTMLAnchorElement>, href: string) => {
    e.preventDefault();
    setIsMenuOpen(false);
    const targetId = href.replace('#', '');
    const elem = document.getElementById(targetId);
    if (elem) {
      const offset = 80;
      const elementPosition = elem.getBoundingClientRect().top;
      const offsetPosition = elementPosition + window.pageYOffset - offset;

      window.scrollTo({
        top: offsetPosition,
        behavior: 'smooth'
      });
      window.history.pushState(null, '', href);
    }
  };

  return (
    <>
      <header 
        className={`fixed top-0 left-0 w-full z-[1000] transition-all duration-700 ease-in-out px-4 md:px-8 lg:px-12 pointer-events-none
          ${scrolled ? 'py-4' : 'py-6 md:py-8 lg:py-12'}
        `}
      >
        <div className={`max-w-[1600px] mx-auto flex justify-between items-center transition-all duration-700 pointer-events-auto
          ${scrolled 
            ? 'bg-black/60 backdrop-blur-2xl py-2 md:py-3 px-5 md:px-8 rounded-full border border-white/10 shadow-2xl' 
            : 'bg-transparent py-0 px-0'
